import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十六卦豫 雷地豫 震上坤下","description":"周易 - 第十六卦豫 雷地豫 震上坤下","frontmatter":{"title":"第十六卦豫 雷地豫 震上坤下","description":"周易 - 第十六卦豫 雷地豫 震上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/017.md","filePath":"zh/classics/zhouyi/017.md"}'),l={name:"zh/classics/zhouyi/017.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="雷地豫" tabindex="-1">雷地豫 <a class="header-anchor" href="#雷地豫" aria-label="Permalink to “雷地豫”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利建侯行师。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>豫，刚应而志行，顺以动，豫。豫，顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>鸣豫，凶。象 曰：初六鸣豫，志穷凶也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>介于石，不终日，贞吉。象曰：不终日，贞吉；以中正也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>盱豫，悔。迟有悔。象曰：盱豫有悔，位不当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>由豫，大有得。勿疑。朋盍簪。象曰：由豫，大有得；志大行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>贞疾，恒不死。象曰：六五贞疾，乘刚也。恒不死，中未亡也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>冥豫，成有渝，无咎。象曰：冥豫在上，何可长也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
